    body: "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Payments</title>\n    <link rel=\"stylesheet\" href=\"../../../service-page.css\" />\n    <style>\n      .grid { display: grid; gap: 0.75rem; }\n      .row {\n        display: flex;\n        gap: 0.75rem;\n        align-items: baseline;\n        justify-content: space-between;\n        flex-wrap: wrap;\n      }\n      .name { font-weight: 600; }\n      .empty { color: var(--muted-foreground); }\n      .error { border-color: var(--destructive); color: var(--destructive); }\n      .tag {\n        font-size: 0.75rem;\n        border: 1px solid var(--border);\n        border-radius: 999px;\n        padding: 0.05rem 0.5rem;\n        color: var(--muted-foreground);\n      }\n    </style>\n  </head>\n  <body>\n    <main class=\"zv-stack\">\n      <section class=\"zv-card zv-stack\">\n        <div>\n          <h2>Active gateways</h2>\n          <p class=\"zv-muted\" id=\"active-hint\">Loading…</p>\n        </div>\n        <div class=\"grid\" id=\"active\"></div>\n      </section>\n\n      <section class=\"zv-card zv-stack\">\n        <div>\n          <h2>Payment plugins</h2>\n          <p class=\"zv-muted\" id=\"catalogue-hint\">Loading…</p>\n        </div>\n        <div class=\"grid\" id=\"catalogue\"></div>\n      </section>\n    </main>\n\n    <script type=\"module\">\n      // Four levels up from /runtime/service-page-assets/<service>/<bundle>/<file>\n      // is the API root this page was served from.\n      const apiRoot = new URL(\"../../../../\", location.href).pathname.replace(/\\/$/, \"\");\n      // The plugin these gateways extend. Named explicitly: a catalogue asking\n      // for the wrong owner lists nothing while looking like it worked.\n      const OWNER = \"@zelavis/ecommerce\";\n\n      const el = (id) => document.getElementById(id);\n\n      async function api(path) {\n        const response = await fetch(apiRoot + path, {\n          headers: { accept: \"application/json\" },\n        });\n        const text = await response.text();\n        const body = text ? JSON.parse(text) : undefined;\n        if (!response.ok) {\n          throw new Error(body?.error ?? `Request failed (${response.status})`);\n        }\n        return body;\n      }\n\n      function card(children) {\n        const row = document.createElement(\"div\");\n        row.className = \"zv-card row\";\n        for (const child of children) row.append(child);\n        return row;\n      }\n\n      function text(value, className) {\n        const span = document.createElement(\"span\");\n        if (className) span.className = className;\n        span.textContent = value;\n        return span;\n      }\n\n      async function renderActive() {\n        const list = el(\"active\");\n        list.replaceChildren();\n        try {\n          const { providers = [] } = await api(\"/commerce/payments/providers\");\n          el(\"active-hint\").textContent = providers.length\n            ? \"Gateways this installation can take payments through.\"\n            : \"No payment gateway is registered.\";\n          for (const provider of providers) {\n            const name = provider.name ?? provider;\n            list.append(card([text(name, \"name\"), text(\"registered\", \"tag\")]));\n          }\n        } catch (cause) {\n          el(\"active-hint\").textContent = cause.message;\n          el(\"active-hint\").classList.add(\"error\");\n        }\n      }\n\n      async function renderCatalogue() {\n        const list = el(\"catalogue\");\n        list.replaceChildren();\n        try {\n          // Scoped to what extends this plugin. A general catalogue would list\n          // a dashboard theme beside a payment gateway and mean nothing here.\n          const { extensionPoints = [] } = await api(\n            `/runtime/extensions?owner=${encodeURIComponent(OWNER)}`,\n          );\n          const extensions = extensionPoints[0]?.extensions ?? [];\n          el(\"catalogue-hint\").textContent = extensions.length\n            ? \"Gateways that can be installed into this plugin.\"\n            : \"No payment plugins are registered on this installation.\";\n          for (const extension of extensions) {\n            list.append(\n              card([\n                text(extension.marketplace?.title ?? extension.name, \"name\"),\n                text(extension.status, \"tag\"),\n              ]),\n            );\n          }\n        } catch (cause) {\n          el(\"catalogue-hint\").textContent = cause.message;\n          el(\"catalogue-hint\").classList.add(\"error\");\n        }\n      }\n\n      await Promise.all([renderActive(), renderCatalogue()]);\n    </script>\n  </body>\n</html>\n",
